mapper.select:
SELECT CASE WHEN b.download_type IS NOT NULL THEN COALESCE(b.download_content, b.msg_text) END AS content
FROM bt_bot_session_msg a
LEFT JOIN bt_bot_session_msg_text b ON a.msg_id = b.msg_id
WHERE a.transaction_id = #{transactionId}
  AND b.paragraph_group = #{group}
ORDER BY b.paragraph_sortby
